        stop: external_exports.string().optional().describe("\uC774 reqId \uC758 \uC6CC\uCE58\uC5D0 \uC815\uC9C0 \uC2E0\uD638\uB97C \uBCF4\uB0B8\uB2E4. condition \uC5C6\uC774 \uB2E8\uB3C5 \uC0AC\uC6A9."),
        stopAll: external_exports.boolean().optional().describe("true \uBA74 \uC9C4\uD589 \uC911\uC778 \uBAA8\uB4E0 \uC6CC\uCE58\uB97C \uC815\uC9C0\uC2DC\uD0A8\uB2E4.")
